<template><div><DsPageHeader title="Modelos de modo texto" subtitle="Geração de arquivo por modelo" icon="file-text"/><DsPageShell><DsSearchInput v-model="search" placeholder="Buscar modelo" @enter="load"/><div v-for="m in modelos" :key="m.codModelo" class="flex justify-between border-b py-3"><span><strong>{{ m.nome }}</strong><small class="block text-gray-500">{{ m.totalSecoes }} seção(ões)</small></span><DsButton size="sm" @click="download(m)">Baixar .txt</DsButton></div><DsButton class="mt-4" variant="secondary" to="/variaveis">Voltar</DsButton></DsPageShell></div></template>
<script setup lang="ts">definePageMeta({layout:'default'});const api=useVariaveisApi();const search=ref('');const modelos=ref<Array<{codModelo:number;nome:string;totalSecoes:number}>>([]);async function load(){modelos.value=(await api.listModelosModoTexto(search.value)).data||[]}async function download(m:{codModelo:number;nome:string}){const blob=await api.downloadModoTexto(m.codModelo);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`modo_texto_${m.nome}.txt`;a.click();URL.revokeObjectURL(url)}onMounted(load)</script>
